    "title": "Police Aur Defense Medical: Lasik Surgery, Tattoos Aur Flat Foot Ke Strict Rules",
    "excerpt": "CAPF, Army aur State Police me medical standards ki reality. Kya Lasik allowed hai aur tattoo rules kya kehte hain?",
    "publishedAt": "2026-03-26",
    "readingTime": "8 min read",
    "author": "Sarkari Afsar Editorial",
    "category": "Exam Prep",
    "tags": ["medical test", "lasik", "tattoo", "defense", "police"],
    "intro": "Defense (Army, Navy, Airforce), CAPF (BSF, CRPF, CISF), aur State Police ki jobs me medical fitness sirf ek formality nahi hoti, balki selection ka ek core filter hoti hai. Written exam me top karne wale candidates bhi minor medical issues ki wajah se reject ho jate hain. Sabse zyada confusion teen cheezon ko lekar hota hai: Lasik eye surgery, body tattoos, aur flat foot/knock knees. Candidates aksar YouTube videos dekh kar assume kar lete hain ki 'surgery chhupa lenge' ya 'tattoo remove karwa lenge', lekin medical boards ke paas advanced machines aur strict guidelines hoti hain. Is detailed post me hum official medical manuals ke hawale se baat karenge. Hum samjhenge ki kis size ka tattoo allowed hai, Lasik surgery kis age me aur kis limit tak valid maani jati hai, aur physical deformities ko check karne ka actual clinical process kya hota hai. In rules ko pehle se janna isliye zaroori hai taaki aap galat exam me apna keemti waqt aur mehnat waste na karein.",
    "sections": [
      {
        "heading": "1. Lasik Surgery Aur Vision Standards",
        "paragraphs": [
          "Armed Forces (Army/Navy/Airforce) me Lasik surgery strictly banned hai. Wahan aankhon ka natural vision hi required hota hai, aur corneal topography machines se surgery easily pakdi jati hai. Chhupane ki koshish karne par permanent debarment ho sakta hai.",
          "Wahi dusri taraf, CAPF (Sub Inspector aur Constable) aur kuch State Police jobs me Lasik allowed hota hai, lekin iski strict conditions hain. Surgery ko hue kam se kam 6 mahine se 1 saal ka waqt beet chuka hona chahiye, aur candidate ki age surgery ke waqt 20 ya 21 saal se upar honi chahiye. Vision standard 6/6 aur 6/9 ke bracket me aana chahiye bina kisi residual complication ke."
        ]
      },
      {
        "heading": "2. Tattoos Ke Detailed Rules",
        "bullets": [
          "Content Rule: Religious symbols (jaise 'Om', 'Trishul') ya naam ke chote tattoos normally permitted hote hain, but unka meaning offensive ya derogatory nahi hona chahiye.",
          "Location Rule: Tattoo body ke us part par hona chahiye jo salute karte waqt visible na ho. Jaise ki left forearm ka inner part ya back of the hand allowed ho sakta hai, par right hand (saluting hand) par tattoo completely banned hota hai.",
          "Size Rule: Tattoo ka size us body part (jaise elbow se wrist tak ka area) ke 1/4th (25%) size se bada nahi hona chahiye. Agar bada tattoo hai, to laser removal hi ekmatra option bachta hai, aur uske scars heal hone chahiye."
        ]
      },
      {
        "heading": "3. Flat Foot Aur Knock Knees Check",
        "paragraphs": [
          "Flat foot check karne ke liye medical officer usually 'Water Test' karte hain ya glass plate par khada karte hain. Agar aapke foot ke arch ka gap visible nahi hai, to wo heavy boots pehen kar long distance march karne me problem create karega, isliye ise unfit mana jata hai. Kuch special shoes se bachpan me ise theek kiya ja sakta hai, par adult age me ye permanent disqualification hota hai.",
          "Knock knees (ghutne takrana) check karne ke liye candidate ko seedha khada kiya jata hai. Agar dono ghutne touch ho rahe hain aur ankles ke beech gap hai, to ye running aur obstacle crossing ke liye unfit mana jata hai."
        ]
      }
    ]
