    "title": "Exam Center Par E-Aadhaar vs Physical Aadhaar: Acceptability Rules",
    "excerpt": "Kya exam center par phone me Aadhaar dikhana ya normal printout le jana valid hai? Janiye safe options.",
    "publishedAt": "2026-03-28",
    "readingTime": "7 min read",
