    "slug": "epf-withdrawal-transfer-joining-govt-job",
    "title": "Private Se Sarkari Naukri: EPF/PF Withdrawal Ya EPS Transfer Kaise Karein?",
    "excerpt": "Private sector chhod kar Govt job join karte waqt purane UAN/PF account ka kya karein? Rule of transfer.",
    "publishedAt": "2026-03-29",
