          "Panel aapse Current Affairs, Banking Awareness, aur aapke graduation subjects se cross-questions karta hai. Focus is baat par hota hai ki agar aapko answer nahi pata, to aap us situation ko politely aur confidently kaise handle karte hain ('Sorry Sir, I don't know' kehne ka tarika).",
          "Dress code strictly formal, aur body language extremely professional honi chahiye."
