          "Isliye SSC me interview hata kar 'Computer Proficiency' aur 'Data Entry Speed' test rakha gaya hai. DV stage me unhe sirf aapki identity aur documents ki 100% authenticity chahiye. Yahan aapka attitude matter nahi karta, aapke documents ki legitimacy matter karti hai."
