          "Agar CGL aapka target hai, to apna pura focus Tier-2 ke marks maximize karne par lagayein, kyunki selection totally marks based hai. Lekin, MS Excel aur fast Typing seekhna bilkul na bhoolein, kyunki marks hone ke bawajood skill test me fail hue to poori mehnat bekar ho jayegi."
