    "slug": "railway-alp-technician-medical-a1-standard-details",
    "title": "Railway ALP A1 Medical Standard Detailed Breakdown: Vision, Color Blindness Aur Rules",
    "excerpt": "RRB Assistant Loco Pilot (ALP) ke liye sabse strict A1 medical test me kya-kya check hota hai aur fail hone par options.",
