          "Chai pilana ya safai karna MTS ka kaam nahi hota. Iske liye departments ab specialized agency se outsourcing (contractual workers) hire karte hain. Ek graduate MTS usually LDC (Lower Division Clerk) ke assisting role me desk par baithta hai, section officer ki files manage karta hai, aur office routine work dekhta hai."
