    "title": "Govt Quarters vs HRA Rules: Type I, II, III Quarters Kaise Allot Hote Hain?",
    "excerpt": "HRA (House Rent Allowance) claim karne aur Government Quarter allotment ke rules, maintenance aur license fee ki details.",
    "publishedAt": "2026-04-10",
