          "Type II (Level 2 to Level 5): Ye quarters LDC, UDC, aur Auditors ke liye hote hain. Inme generally 2 rooms, kitchen, balcony milti hai.",
          "Type III (Level 6 to Level 8): Inspectors (Income Tax/Excise), Station Masters aur ASO rank officers ko ye allot hote hain. Ye proper 2 BHK type spacious flats hote hain.",
