    "slug": "sports-quota-recruitment-govt-jobs-trials-certificate",
    "title": "Sports Quota Recruitment Reality: Certificate Validity, Trials Aur Out-of-Turn Promotion",
    "excerpt": "Sarkari naukriyo me khel kote (Sports Quota) se bharti ka detailed process. National vs State level certificate marks aur duty pattern.",
    "publishedAt": "2026-04-25",
