    "slug": "passport-foreign-travel-rules-govt-employees",
    "title": "Sarkari Karmchari Ke Liye Passport Aur Foreign Travel Ke Sakht Niyam: NOC Aur Vigilance",
    "excerpt": "Government job me aane ke baad passport banwane, visa lene aur foreign trip par jane ke detailed DoPT aur MEA rules.",
    "publishedAt": "2026-05-10",
    "readingTime": "14 min read",
    "author": "Sarkari Afsar Editorial",
    "category": "Guides",
    "tags": ["passport rules", "foreign travel", "noc", "vigilance", "govt employee"],
    "intro": "Ek aam nagrik (citizen) ke liye passport banwana aur foreign ghumne jana aajkal bahut aasan process hai, bas online form bharo aur ticket book kar lo. Lekin agar aap Central ya State Government ke employee hain, to aap national security aur official secrets act ke dayre me aate hain. Sarkari naukri me aane ke baad aap bina apne department ko bataye na to naya passport apply kar sakte hain, na purana renew karwa sakte hain, aur na hi chupke se Dubai ya Thailand ki trip par ja sakte hain. Agar aapne bina permission foreign travel kiya, to ise 'Absconding' aur 'Gross Misconduct' mana jata hai, jiske liye seedha dismissal (naukri se nikalna) ka rule hai. Is extremely detailed aur legal guide me hum Ministry of External Affairs (MEA) aur DoPT ke un complex protocols ko samjhayenge, jinke tehat ek sarkari babu ko 'Identity Certificate' (Annexure B), Prior Intimation, aur Leave Sanction process se guzarna padta hai apne foreign trip ko legally safe banane ke liye.",
    "sections": [
      {
        "heading": "1. Naya Passport Banwana Ya Renew Karna: The 'Prior Intimation' Rule",
        "paragraphs": [
          "Agar aap government job join kar chuke hain aur aapko apna pehla passport apply karna hai, to aap direct passport office nahi ja sakte. Pehle aapko apne Head of Department (HOD) ko ek formal 'Prior Intimation' (P.I.) letter dena hota hai jisme aap batate hain ki 'Main passport apply karne ja raha hu'. Jab aap passport ka online form bharte hain, to usme aapko apne employment type me 'Government' select karna hota hai aur is P.I. letter ki receipt details daalni hoti hain.",
          "Identity Certificate (Annexure B): Agar aapko passport ki tatkal (urgent) zarurat hai ya aap chahte hain ki police verification passport banne ke baad ho, to aap apne department se 'Annexure B' (Identity Certificate) maang sakte hain. Ye ek certificate hota hai jisme department likh kar deta hai ki 'Ye hamara bonafide karmchari hai aur is par koi criminal ya vigilance case pending nahi hai, iska passport banne par humein koi objection nahi hai'. Lekin dhyan rahe, Annexure B issue karna HOD ka discretion (marzi) hai, ye aapka haq nahi hai."
        ]
      },
      {
        "heading": "2. Visa Aur Foreign Travel Ke Liye 'Ex-India Leave' Aur NOC",
        "bullets": [
          "Passport hath me aane ka matlab ye nahi ki aap ticket book kar lein. Kisi bhi foreign country me jane se pehle (chahe wo 3 din ka vacation hi kyu na ho), aapko apne department se 'Ex-India Leave' (India ke bahar jane ki chhutti) sanction karwani padti hai.",
          "Aapko ek detailed proforma bharna hota hai jisme ye declare karna hota hai ki: Aap kis country ja rahe hain? Wahan aapka address kya hoga? Trip ka duration kya hai? Aur sabse important: Is trip ko sponsor kon kar raha hai (Aap khud, koi relative, ya koi foreign agency)?",
          "Vigilance Clearance: Chhutti sanction hone se pehle aapki file Vigilance section me jati hai ye check karne ke liye ki aapke khilaf koi departmental enquiry, corruption ka case ya FIR to pending nahi hai. Agar vigilance clearance ruk gaya, to aapki trip cancel mani jayegi."
        ]
      },
      {
        "heading": "3. The Trap of Foreign Hospitality (FCRA Rules)",
        "paragraphs": [
          "Sarkari karmchariyon par Foreign Contribution (Regulation) Act, 2010 (FCRA) lagoo hota hai. Aap kisi bhi foreign trip ke dauran kisi foreign government, agency, ya foreign national se muft me hotel stay, expensive gifts, ya cash accept nahi kar sakte. Ise foreign hospitality kaha jata hai aur ise bina Ministry of Home Affairs (MHA) ki permission ke accept karna ek criminal offence hai.",
          "Agar aapke foreign trip ka kharcha aapka real brother/sister (jo NRI hai) utha raha hai, to aapko explicitly is baat ka proof (unka bank statement aur relation) apne department me jama karna padta hai taaki baad me Disproportionate Assets (aay se adhik sampatti) ki enquiry na baith jaye."
        ]
      },
      {
        "heading": "4. Overstaying Abroad: Dismissal Ka Khatra",
        "paragraphs": [
          "Kayi karmchari foreign jate hain aur wahan beemar padne ka bahana karke chhutti extend karne ki koshish karte hain, ya wahan koi aur part-time kaam dhundhne lagte hain. DoPT ka rule bohot strict hai: Agar ek government employee foreign trip par jakar apni sanctioned leave limit cross kar deta hai (without an extreme medical emergency proved by foreign doctors), to use 'unauthorized absence' me gina jata hai.",
          "Agar absent 1 ya 2 mahine se cross ho jaye, to department Article 311 ke tehat seedha Ex-Parte enquiry (aapki gair maujudgi me) conduct karta hai aur aapko service se permanently dismiss kar diya jata hai. Isliye hamesha return ticket aur visa validity ko strictly observe karna chahiye."
        ]
      }
    ]
