    "tags": ["pay fixation", "fr 22", "promotion", "salary increment", "dopt rules"],
    "intro": "Jab ek sarkari karmchari ko uski service life me promotion milta hai (jaise LDC se UDC, ya Auditor se Senior Auditor), to office me mithaai batne ke theek baad account section (establishment) use ek 1 page ka 'Option Form' thama deta hai. Ye form Fundamental Rules (FR) 22(I)(a)(1) ke tehat hota hai. Is form me karmchari se pucha jata hai ki: 'Aap apni nayi salary ka calculation aaj (Date of Promotion) se karwana chahte hain, ya apne aane wale agle saalana increment (Date of Next Increment - DNI) wale mahine se?' Zyada tar employees bina hisab lagaye option A (aaj se) par tick kar dete hain, kyunki unhe lagta hai agle mahine ki salary thodi badh kar aayegi. Lekin unhe ye andaza nahi hota ki is choti si ignorance (agyanta) ki wajah se unhe apne aane wale 20 saal ki service me lakho rupaye ka compound loss ho sakta hai. Is highly technical aur financial post me hum Pay Matrix ki us mathematics ko deeply decode karenge jisse aap apne promotion ke waqt sahi option chunkar maximum financial life-time gain le sakein.",
    "sections": [
      {
        "heading": "1. What is FR 22(I)(a)(1) Pay Fixation?",
        "paragraphs": [
          "Jab aap promote hote hain, to government aapko higher responsibility lene ke liye reward karti hai. Rule ke mutabiq, aapki current basic pay me pehle ek 'Notional (kalpanik) Increment' (approx 3%) joda jata hai. Us badhi hui value ko phir next higher Pay Level (aapki nayi post ka column) me dhundha jata hai.",
          "Agar wo exact value wahan match karti hai to theek, warna aapko us column me aane wali agli immediate higher basic pay de di jati hai. Is process ko Pay Fixation kehte hain. Par sawal ye hai ki ye calculation kis din (kis date ko) kiya jaye?"
        ]
      },
      {
        "heading": "2. Option A: Fixation From Date of Promotion (DOP)",
        "bullets": [
          "Kese Kaam Karta Hai: Agar aap 15 October ko promote hue, aur aapne Option A chuna, to aapki purani salary me immediately ek increment lagakar nayi pay level me fit kar diya jayega. Aapko aane wale mahine (November) se hi achi badhi hui salary (immediate gain) milne lagegi.",
          "Nuksan (Loss) Kahan Hai: Government rule kehta hai ki agla saalana increment (jo aapko July ya Jan me milna tha) tabhi milega jab aap apni nayi post par kam se kam 6 mahine poore kar lenge.",
          "Agar aapka normal increment 1st January ko aana tha, aur aapne 15 October ko promote hokar Option A chuna, to 1st January aane par aapke 6 mahine poore nahi honge. Iska matlab aapka January wala increment zero ho jayega, aur aapka naya annual cycle shift hokar agli 1st July ko chala jayega. Aapne us 1 saalana increment (lagbhag ₹1500 per month base) ka loss hamesha ke liye utha liya."
        ]
      },
      {
        "heading": "3. Option B: Fixation From Date Of Next Increment (DNI)",
        "paragraphs": [
          "Kese Kaam Karta Hai: Agar aapne Option B chuna, to aap account section ko bol rahe hain: 'Main aaj promote ho raha hu, aaj mujhe nayi post ki simple starting basic (ya purani value jo nayi level me fit baithti hai bina extra increment ke) de do. Jab mera normal increment (DNI) 1st January ko aayega, tab aap mera promotion wala increment aur normal saalana increment dono ek sath laga kar pay fix karna'.",
          "Fayda (The Smart Move): Is approach me aapko initial 2 mahine salary slightly kam aayegi (immediate loss). Lekin jab 1st January aayegi, to aapko 2 increment (ek annual aur ek promotional) ek sath milenge. Aapki Basic Pay sidhe do jump maregi Pay Matrix me. Isse aap long term me apne un batchmates se basic me agey nikal jayenge jinhone Option A chuna tha."
        ]
      },
      {
        "heading": "4. Thumb Rule To Decide Faster",
        "paragraphs": [
          "Jab bhi Option Form samne aaye, to in do dates ke beech ka gap dekhein: Aapki Date of Promotion aur aapki Date of Annual Increment (DNI).",
          "Thumb Rule: Agar aapka promotion aapke DNI se lagbhag 4 se 6 mahine pehle ho raha hai (Jaise aap Jan me promote hue aur agla increment July me hai), to hamesha 'Option B' (DNI) sunehra (golden) hota hai. Par agar aapka promotion increment ke theek baad ya increment se kafi lamba gap le raha hai, tab case-by-case calculation matrix dekh kar karni padti hai. Hamesha department ke account clerks (jo in tables par hi kaam karte hain) unse 5 minute request karke apni matrix plot karwa lein uske baad hi form par sign karein."
        ]
      }
    ]
