    "slug": "major-vs-minor-penalty-ccs-cca-rules-enquiry",
    "title": "Sarkari Job Me Major Penalty Aur Minor Penalty Ka Asar: Promotion Aur Career Par",
    "excerpt": "CCS (CCA) Rules 14 aur 16 ke darawane prawadhan. Censure aur Withholding Increment ka promotion par kya directly impact padta hai.",
    "publishedAt": "2026-05-16",
