    "title": "CGHS Facility Aur Medical Reimbursement: Parents Aur Dependents Ko Cover Karne Ke Asli Rules",
    "excerpt": "CGHS health card me parents, wife aur unemployed bachon ko add karne ka income limit rule aur emergency private hospital reimbursement process.",
    "publishedAt": "2026-05-17",
    "readingTime": "12 min read",
