          "Naye Joiners Ke Liye Special Rule: Jo karmchari nayi job join karte hain, unhe shuruati 8 saalo tak har saal (every year) LTC milti hai. Pehle 3 saal wo apne Home Town (address declared in service book) ja sakte hain, aur 4th year me All India kahin bhi ja sakte hain. Ye cycle aagle 4 saalo (5th to 8th year) tak repeat hota hai. 8 saal pure hone ke baad wo normal 4-year block system me aa jate hain."
