          "Level 6 to Level 8 (Station Master, ASO, Inspector): Inhe Train ka AC-2 Tier allowed hota hai. Ye generally flight ke liye eligible nahi hote, exception ke taur par jab DoPT specially North-East (NER), Jammu & Kashmir, ya Andaman (A&N) jane ke liye special chhoot (relaxation) nikalta hai.",
