          "Agar LTC fraud prove ho gaya, to wo amount 2% penal interest ke sath recover kiya jata hai, aage aane wali LTCs permanently block kar di jati hain, aur CCS (CCA) Rules ke tehat Major Penalty (jaise demotion ya dismissal) lagayi jati hai. Isliye LTC claims me 100% honesty aur exact bill tracking maintain karni chahiye."
