    "slug": "working-couples-hra-quarter-rules-govt-jobs",
    "title": "Working Couples HRA Rules: Agar Pati-Patni Dono Sarkari Naukri Me Hon To Kise HRA Milega?",
    "excerpt": "DoPT ke HRA aur Government Quarter allotment rules agar husband aur wife dono Central ya State government me employed hain.",
    "publishedAt": "2026-05-20",
    "readingTime": "11 min read",
