    "tags": ["hra", "working couples", "allowances", "government quarters", "salary rules"],
    "intro": "Aaj kal bahut se couples (Pati aur Patni) dono govt jobs me hote hain. Aise me ek sabse bada financial confusion create hota hai unke House Rent Allowance (HRA) aur sarkari awas (Quarter) allotment ko lekar. 'Kya dono ko HRA mil sakta hai?', 'Agar patni ne quarter liya hai, to kya pati dusre department se HRA utha sakta hai?' aur 'Agar dono alag-alag shehron me posted hain to kya niyam hain?' In sawalo ke jawab DoPT (Department of Personnel and Training) ke specific FRSR rules me chhupe hain. Agar aap in rules ko ignore karke double benefits uthate hain, to aage chalkar audit team us paise ki recovery heavy interest ke sath karti hai. Is informative guide me hum working couples ke HRA claim karne ke saare combinations aur unki legality ko practically explain karenge.",
    "sections": [
      {
        "heading": "1. Scenario A: Dono Ek Hi Station (Shehar) Me Posted Hain",
        "paragraphs": [
          "Condition 1 (No Quarter): Agar husband aur wife dono Delhi (ya kisi ek shehar) me posted hain aur unhone koi sarkari quarter allot nahi karwaya hai (yani khud ke ghar me ya private rent par reh rahe hain), to dono ko apni-apni salary me individually poora HRA milega. Isme koi rok nahi hai.",
          "Condition 2 (One Allotted Quarter): Agar dono ek hi shehar me hain aur kisi ek ne (man lijiye wife ne) apne department se Government Quarter allot karwa liya hai. To wife ka HRA automatically kat jayega. Par yahan strict rule ye hai ki aisi situation me Husband ko bhi HRA milna band ho jayega (kyunki wo same accommodation share kar rahe hain). Agar husband ne is jankari ko chupakar apne department se HRA liya, to ye illegal hoga aur audit me pakde jane par recovery hogi."
        ]
      },
      {
        "heading": "2. Scenario B: Dono Alag-Alag Station (Cities) Me Posted Hain",
        "bullets": [
          "Agar husband Delhi me posted hai aur wife Mumbai me posted hai, to ye dono alag-alag duty stations mane jayenge.",
          "Aisi sthiti me, agar husband Delhi me quarter leta hai, to uska HRA katega, lekin wife ko Mumbai me apna HRA poora milta rahega (kyunki uska base aur jarurat alag hai).",
          "Dono apni apni cities me completely independent employees ki tarah treat kiye jayenge HRA aur quarters ke mamle me."
        ]
      },
      {
        "heading": "3. Scenario C: Ek Central Govt Me, Ek State Govt/PSU Me",
        "paragraphs": [
          "Rule ye nahi dekhta ki dusra partner Central me hai ya State me. Agar spouse kisi bhi aisi entity (State Govt, Railway, PSU, Autonomous body, ya University) me kaam karta hai jahan government fund involve hai, to HRA restriction rules same apply honge.",
          "Agar State Govt employee wife ne quarter liya hai, to Central Govt me kaam karne wale husband ko HRA surrender karna padega (agar station same hai)."
        ]
      },
      {
        "heading": "4. Joint Declaration (Mandatory Undertaking)",
        "paragraphs": [
          "Double claims aur fraud rokne ke liye, har department saal me ek baar apne employees se HRA aur Accommodation ko lekar ek 'Joint Declaration / Undertaking Form' bharwata hai. Is form me aapko explicitly batana hota hai ki aapke spouse kahan employed hain aur unhone quarter draw kiya hai ya nahi.",
          "Is form ko seriously fill karein. Agar aapka spouse baad me kabhi quarter surrender karta hai aur private shift hota hai, to aapko turant apne account section ko notify karna chahiye taaki aap dono ka HRA rules ke mutabiq wapas start ho sake."
        ]
      }
    ]
