    "slug": "dpc-apar-acr-grading-promotion-rules",
    "title": "DPC Aur APAR Grading: 'Very Good' Benchmark Na Milne Par Promotion Kaise Ruke",
    "excerpt": "Departmental Promotion Committee (DPC) kaise kaam karti hai? APAR (ACR) me 'Good' ya 'Average' grading aane par career ka loss.",
