    "readingTime": "13 min read",
    "author": "Sarkari Afsar Editorial",
    "category": "Guides",
    "tags": ["dpc", "apar", "acr", "promotion", "benchmarks"],
    "intro": "Sarkari naukri me aapki mehnat aur performance ka ek hi official document hota hai, jise APAR (Annual Performance Assessment Report) ya purani bhasha me ACR (Annual Confidential Report) kehte hain. Jab aapke promotion ka time aata hai, to ek Departmental Promotion Committee (DPC) baithti hai. DPC aapka chehra ya aapki baatein nahi janti, wo sirf aapke pichle 5 saal ke APAR dossiers (files) check karti hai. Aam taur par karmchari is report ko formality samajhte hain aur apne Reporting Officer se jhagda kar lete hain. Jab DPC result nikalta hai aur unke juniors promote ho jate hain aur unki file reject ho jati hai, tab unhe benchmark grading ka harsh reality pata chalta hai. Is post me hum DoPT ke promotion benchmarks ('Very Good' rule) ko explain karenge aur batayenge ki adverse remarks ke khilaf representation (appeal) kaise lagayi jati hai.",
    "sections": [
      {
        "heading": "1. What is APAR? Reporting, Reviewing & Accepting Officers",
        "paragraphs": [
          "Har financial year (April se March) ke khatam hone par aapko apna APAR (self-appraisal) bharna hota hai. Isme aap likhte hain ki aapne saal bhar me kya targets achieve kiye. Ye file aapke immediate boss yani 'Reporting Officer' ke paas jati hai, jo aapko 1 se 10 ke scale par marks (grading) deta hai.",
          "Uske baad file uske bhi upar wale boss 'Reviewing Officer' ke paas jati hai jo marks ko agree ya modify karta hai. Final approval 'Accepting Authority' deta hai. In officers ka diya gaya ek-ek shabd aapki professional image tay karta hai."
        ]
      },
      {
        "heading": "2. The 'Very Good' Benchmark Rule (Life Changer)",
        "bullets": [
          "Pehle promotion pane ke liye 'Good' grading (5 se 6 marks) chal jati thi. Lekin 7th Pay Commission aur DoPT ke strict rules ke baad, ab lagbhag sabhi regular promotions aur MACP (financial upgradation) ke liye 'Very Good' (6 to 8 marks) benchmark mandatory kar diya gaya hai.",
          "Agar DPC aapke pichle 5 saal ki files check karti hai aur usme se 2 saal aapki grading sirf 'Good' ya 'Average' hai, to aap us saal promotion ke liye strictly Ayogya (Unfit) declare kar diye jayenge. Aapka promotion tab tak delay hota rahega jab tak aap aage aane wale saalo me 'Very Good' grading se us average file ko replace nahi kar dete."
        ]
      },
      {
        "heading": "3. DPC Procedure: Zone of Consideration",
        "paragraphs": [
          "Jab department me 10 posts khali hoti hain, to DPC sirf top 10 logo ko nahi bulati. Wo ek 'Zone of Consideration' banati hai (jaise vacancies ka 2.5 ya 3 times). Yani 10 posts ke liye top 30 logo ki files check hongi.",
          "DPC is zone me aane wale sabhi 30 logo ke grading check karti hai. Jo jo 'Fit' (Very Good benchmark meet karte hain) paaye jate hain, unhe seniority list ke order me top 10 seats de di jati hain. Agar top wala unfit hua, to uske neeche wala (junior) use supersede (bypassing) karke promote ho jata hai."
        ]
      },
      {
        "heading": "4. Representation Against Adverse/Low Grading",
        "paragraphs": [
          "Ek achi baat ye hai ki rules me transparency laayi gayi hai. Pura APAR finalize hone ke baad aapko padhne ke liye diya jata hai. Agar aapke boss ne aapse personal dushmani nikalte hue aapko 4 marks (Average) diye hain ya koi Adverse Remark likha hai, to aapko chup nahi baithna hai.",
          "Aapke paas officially 15 din ka time hota hai jiske andar aap HOD/Competent Authority ko formal 'Representation' (Appeal) bhej sakte hain. Aap apne proofs (emails, work logs) attach karke claim kar sakte hain ki grading biased hai. Ek impartial committee usko review karke aapke marks upgrade kar sakti hai taaki aapka DPC me nuksan na ho."
        ]
      }
    ]
