    "slug": "study-leave-rules-govt-employees-phd-higher-education",
    "title": "Study Leave Rules: Sarkari Karmchari Padhai Ya PhD Ke Liye 2 Saalo Ki Paid Leave Kaise Lein",
    "excerpt": "Government job ke dauran higher education (MBA, PhD) ke liye Study Leave lene ka statutory rule, bond aur salary conditions.",
