    "slug": "psu-bank-to-central-govt-pay-protection-fr-22b-rules",
    "title": "PSU/Bank Se Central Govt Job: FR 22B Pay Protection Aur DA Loss Ka Technical Khel",
    "excerpt": "PSU ya Bank chhod kar SSC CGL ya UPSC aane par purani salary kaise bachayi jati hai aur IDA vs CDA me nuksan kyun hota hai.",
    "publishedAt": "2026-05-27",
    "readingTime": "15 min read",
    "author": "Sarkari Afsar Editorial",
    "category": "Guides",
    "tags": ["pay protection", "fr 22b", "psu", "bank job to ssc", "salary rules"],
    "intro": "Bank POs aur Navratna PSUs (jaise ONGC, BHEL, NTPC) ke officers aksar higher administrative power, better location, ya better work-life balance ki talash me SSC CGL (Inspector/ASO) ya State PCS/UPSC ka exam nikal kar Central Government me shift ho jate hain. PSU sector me shuruaati salary aur corporate perks Central Government ke comparison me bahut zyada (heavy) hote hain. Jab selection ho jata hai, to employee ke paas sabse badi anxiety ye hoti hai: 'Main PSU me ₹85,000 in-hand le raha hu, aur meri nayi CGL Level 7 post ki starting ₹65,000 in-hand hai. Kya government meri purani high salary protect karegi?' Jawab DoPT ke FR 22(B) (Pay Protection Rules) me chhipa hai. Halanki Central-to-Central job switch me pay protection bahut smooth aur 100% loss-free hoti hai, lekin PSU/Bank se Central Govt aane me DA (Dearness Allowance) format ka ek bada legal clash (IDA vs CDA) hota hai. Is extremely advanced administrative guide me hum explicitly decode karenge ki PSU se aane wale employee ki pay actually fix kaise hoti hai aur kaunsa major hissa protection list se bahar rehta hai.",
    "sections": [
      {
        "heading": "1. Central-To-Central Govt vs PSU-To-Central Govt",
        "paragraphs": [
          "Scenario A (Central to Central): Agar ek karmchari Central Govt ki Defense ministry me LDC tha (Basic ₹21,700) aur ab CGL crack karke Examiner (Basic ₹44,900) banta hai, to nayi Level 7 ki starting basic automatically ₹44,900 fix hogi (jo bhi max ho, wo milega). Agar wo pehle Level 7 me tha aur dubara level 7 ki dusri post me jata hai, to exactly wahi incremental basic retain (bachayi) kar li jati hai.",
          "Scenario B (PSU/Bank to Central Govt): Yahan mamla ghum jata hai. Public Sector Undertakings (PSUs), Universities, aur Nationalized Banks strictly 'Central Government' nahi hote, ye autonomous ya corporate structures hain. PSU me employees 'IDA' (Industrial Dearness Allowance) pattern par kaam karte hain, jabki Central Govt me 'CDA' (Central Dearness Allowance) pattern chalta hai. Is fundamental mismatch ki wajah se Pay Protection sidhi-sidhi matrix to matrix match nahi karti."
        ]
      },
      {
        "heading": "2. The Mathematical Rule of PSU Pay Protection",
        "bullets": [
          "DoPT guidelines ke according, jab aap PSU/Bank se Central Govt me Direct Recruitment (Exam pass karke) ke through aate hain (with Proper Channel NOC), to Pay Protection specifically di jati hai, par ek calculation method ke sath.",
          "Calculation: Aapke PSU ki 'Basic Pay + DA' ko Central Govt ki us time prevailing 'Basic Pay + DA' ke sath compare kiya jata hai.",
          "The Trap: PSUs me Basic Pay generally bohot high rakhi jati hai, lekin unka DA percentage CDA se alag hota hai. Government account section ye check karta hai ki aapka PSU ka total (Basic+DA) amount Central Govt ke kis Pay Level ke (Basic+DA) bracket me physically fit baith raha hai.",
          "Restriction: Aapki protected (badhai gayi) pay kabhi bhi us nayi vacancy ki maximum authorized basic limit se aage nahi ja sakti. Aur allowances (HRA, Perks, Medical) jo PSU me bohot heavy the, wo completely discard (khatam) kar diye jate hain. Naye allowances completely Central CDA norms (7th Pay Commission) par lagu hote hain."
        ]
      },
      {
        "heading": "3. The 'Probation Period' Catch",
        "paragraphs": [
          "Ek bohot bada rule jo kaafi PSU employees ko pata nahi hota: Pay protection join karte hi pehle din se blindly approve nahi ho jati. Naye department me aane par account section (DDO) probation period ke completion ya temporary orders tak aapki salary normal fresh level (e.g. ₹44,900 basic) par hi set kar deta hai.",
          "Aapko formal 'Pay Fixation' ka application apne HOD ke through Ministry/Finance department ko bhajna padta hai (with PSU service records). Is file ki scrutiny (janch) me 6 mahine se 1 saal lag jata hai. Jab file approval ho kar aati hai, tab pichli date (Notionally) se pay protect ki jati hai aur baaki bacha hua paisa Arrears (pichla bakaya) ke roop me ikattha bank me credit hota hai. Isliye initially thode financial shock ke liye mentally ready rehna chahiye."
        ]
      },
      {
        "heading": "4. Will Seniority and Pension (NPS) Transfer?",
        "paragraphs": [
          "Seniority: Direct Recruitment (Open Exam) pass karke aane par purani service ki rank/seniority permanently zero (lapse) ho jati hai. Aap nayi seniority list me lowest bottom par honge as a fresh joinee.",
          "NPS/PRAN Transfer: Aapka retirement/NPS (PRAN) account completely portable hai. Inter-Sector Shifting (ISS) form bharne par aapka bank/PSU wala NPS corpus easily Central Government employer list me port ho jayega, jisse long-term pension me koi discontinuation nahi aayegi."
        ]
      }
    ]
